function() {
  var el = {{Click Element}};
  var id = (el && el.id) || {{Click ID}} || '';
  var m = String(id).match(/gform_confirmation_message_(\d+)/);
  return m ? m[1] : undefined;
}

function() {
  var id = {{JS - Form ID inviato}};
  if (!id) { return 0; }
  var slots = [{{CFG - Form 1 ID}}, {{CFG - Form 2 ID}}, {{CFG - Form 3 ID}}, {{CFG - Form 4 ID}}];
  for (var i = 0; i < slots.length; i++) {
    var v = String(slots[i] == null ? '' : slots[i]).replace(/^\s+|\s+$/g, '');
    if (v !== '' && v !== '-' && v === String(id)) { return i + 1; }
  }
  return 0;
}

function() {
  var n = {{JS - Form slot}};
  var e = ['', {{CFG - Form 1 evento}}, {{CFG - Form 2 evento}}, {{CFG - Form 3 evento}}, {{CFG - Form 4 evento}}][n];
  e = String(e == null ? '' : e).replace(/^\s+|\s+$/g, '');
  return (n && e && e !== '-') ? e : 'form_inviato';
}

function() {
  var clean = function (v) { v = String(v == null ? '' : v).replace(/^\s+|\s+$/g, ''); return v === '-' ? '' : v; };
  var n = {{JS - Form slot}};
  if (!n) { return ''; }
  var raw = String(['', {{CFG - Form 1 Ads label}}, {{CFG - Form 2 Ads label}}, {{CFG - Form 3 Ads label}}, {{CFG - Form 4 Ads label}}][n] || '').replace(/^\s+|\s+$/g, '');
  if (raw === '-') { return ''; }
  if (raw === '' || raw.toLowerCase() === 'predefinita') { return clean({{CFG - Ads label Form (predefinita)}}); }
  return raw;
}

